/**
 * The `html` component: authored markup placed in the form, holding no value.
 *
 * Everything else a form renders is generated by the engine from configuration. This one type
 * puts author-written markup on the page, so it is the only place where a form definition can
 * carry HTML — which makes it the one place worth being careful about. The markup is sanitized
 * against an allowlist here, at render time, on every surface:
 *
 * - a form definition travels (draft store, submission compatibility, a server round-trip)
 *   and is edited by whoever can open the builder, so "the author is trusted" is a statement
 *   about one moment, not about the document;
 * - sanitizing at render rather than at authoring time means a definition written by hand, or
 *   by any tool other than the builder, is covered too.
 *
 * The sanitizer is string-based rather than DOM-based because the engine core runs without a
 * DOM (Node, the wasm host, the server runtime), and a form must render identically on all
 * three.
 */

export const HTML_COMPONENT_TYPE = "html";

/** Wrapper elements an author can choose for the block. */
export const HTML_BLOCK_TAGS: readonly string[] = [
  "div",
  "section",
  "article",
  "aside",
  "p",
  "span",
  "h1",
  "h2",
  "h3",
  "h4",
  "h5",
  "h6",
  "blockquote",
  "pre"
];

const HTML_BLOCK_TAG_SET: ReadonlySet<string> = new Set(HTML_BLOCK_TAGS);

/** The wrapper element for an `html` component; `div` unless a known tag is configured. */
export function readHtmlTag(configuration: unknown): string {
  if (!configuration || typeof configuration !== "object" || Array.isArray(configuration)) {
    return "div";
  }
  const tag = (configuration as { tag?: unknown }).tag;
  return typeof tag === "string" && HTML_BLOCK_TAG_SET.has(tag.toLowerCase())
    ? tag.toLowerCase()
    : "div";
}

/**
 * Elements the content may contain. Formatting, lists, tables, links and images — everything
 * needed to write an instruction block or a consent notice, and nothing that executes,
 * navigates the page on its own, or collects input (a form's inputs are components).
 * A table keeps its `caption` (its accessible name, WCAG technique H39) and its `colgroup` and
 * `col`; the sanitizer does not reorder, so a caption the
 * author wrote first stays the table's first child.
 */
const ALLOWED_TAGS: ReadonlySet<string> = new Set([
  ...HTML_BLOCK_TAGS,
  "a",
  "abbr",
  "b",
  "br",
  "caption",
  "code",
  "col",
  "colgroup",
  "dd",
  "dl",
  "dt",
  "em",
  "figcaption",
  "figure",
  "hr",
  "i",
  "img",
  "kbd",
  "li",
  "mark",
  "ol",
  "s",
  "small",
  "strong",
  "sub",
  "sup",
  "table",
  "time",
  "tbody",
  "td",
  "tfoot",
  "th",
  "thead",
  "tr",
  "u",
  "ul"
]);

/** Elements dropped *with their content* — what is inside them is not text to keep. */
const VOID_OF_CONTENT_TAGS: ReadonlySet<string> = new Set([
  "script",
  "style",
  "template",
  "iframe",
  "object",
  "embed",
  "noscript"
]);

/** Elements that never take a closing tag, so the serializer must not emit one. */
const SELF_CLOSING_TAGS: ReadonlySet<string> = new Set(["br", "col", "hr", "img"]);

/**
 * Attributes kept on any element. `style` is deliberately absent: a form's look belongs to its
 * binding, and `cssClass` (plus the binding's own CSS) is the supported route to styling — see
 * the `cssClass` capability.
 */
const GLOBAL_ATTRIBUTES: ReadonlySet<string> = new Set([
  "class",
  "id",
  "title",
  "dir",
  "lang",
  "role"
]);

/** Per-element attributes, beyond the global ones. */
const ELEMENT_ATTRIBUTES: Record<string, ReadonlySet<string>> = {
  a: new Set(["href", "target", "rel"]),
  img: new Set(["src", "alt", "width", "height", "loading"]),
  col: new Set(["span"]),
  colgroup: new Set(["span"]),
  td: new Set(["colspan", "rowspan", "headers"]),
  th: new Set(["colspan", "rowspan", "scope", "headers"]),
  ol: new Set(["start", "type"]),
  time: new Set(["datetime"])
};

/** Attributes holding a URL, checked against {@link isSafeUrl}. */
const URL_ATTRIBUTES: ReadonlySet<string> = new Set(["href", "src"]);

/**
 * A URL safe to put in the document. Relative and fragment URLs pass; of the schemes, only the
 * ones that fetch or address rather than execute. `data:` is allowed for images alone, which is
 * how an author embeds a small logo without a second request: it passes only where the URL is
 * loaded as a picture (`context` "image"), never where it is navigated to (`context` "link",
 * the default). Exported because the `image` component's own `src` is held to the same rule
 * (`core/schema/image.ts`).
 */
export function isSafeUrl(value: string, context: UrlContext = "link"): boolean {
  // Character references and control characters are the classic way to smuggle "javascript:"
  // past a prefix check ("javascript&#58;", "java&Tab;script:", "java\tscript:"): the browser
  // decodes the reference and drops the control character, so the URL it navigates to is not
  // the one a raw read sees. The scheme is therefore read from a copy decoded the way an
  // attribute parser decodes it (one pass, numeric and named references) with the control
  // characters removed. Decoding, not stripping: a stripped colon leaves a relative-looking
  // string that would pass.
  return schemeIsSafe(stripControls(decodeCharacterReferences(value)), context === "image");
}

/** Where a URL is used: loaded as a picture, or followed as a link. */
export type UrlContext = "image" | "link";

/** `value` without the C0 and C1 control characters and spaces a browser drops from a URL. */
function stripControls(value: string): string {
  return value.replace(/[\u0000- \u007f-\u009f]/g, "");
}

/** The allowlist read off one normalized form of the URL; see {@link isSafeUrl}. */
function schemeIsSafe(normalized: string, allowImageData: boolean): boolean {
  const scheme = /^([a-z][a-z0-9+.-]*):/i.exec(normalized);
  if (!scheme) {
    // No scheme read, but a reference this decoder does not know, left in the text before the
    // first path, query or fragment character, could still decode to one in the browser.
    // Failing closed on it costs nothing a real URL needs.
    // (The `#` of a numeric reference is not a fragment's.)
    const prefix = /^(?:&#|[^/?#])*/.exec(normalized)?.[0] ?? "";
    return !/&#?[a-z0-9]+;/i.test(prefix);
  }
  const protocol = (scheme[1] ?? "").toLowerCase();
  if (protocol === "data") {
    return allowImageData && /^data:image\/(png|jpe?g|gif|webp|svg\+xml);/i.test(normalized);
  }
  return protocol === "http" || protocol === "https" || protocol === "mailto" || protocol === "tel";
}

/**
 * The named references an attribute value may use to spell the characters that matter to a
 * scheme check: the colon, the whitespace a browser strips out of a URL, and the ASCII
 * punctuation an author might reach for. Letters have no named references in HTML, so a
 * scheme's letters can only be spelt numerically, which the decoder below handles too.
 */
const NAMED_REFERENCES: Readonly<Record<string, string>> = {
  colon: ":",
  Tab: "\t",
  NewLine: "\n",
  nbsp: " ",
  amp: "&",
  lt: "<",
  gt: ">",
  quot: '"',
  apos: "'",
  sol: "/",
  bsol: "\\",
  num: "#",
  quest: "?",
  equals: "=",
  semi: ";",
  excl: "!",
  percnt: "%",
  plus: "+",
  comma: ",",
  period: ".",
  lpar: "(",
  rpar: ")",
  lowbar: "_",
  ast: "*",
  commat: "@",
  dollar: "$",
  tilde: "~",
  grave: "`",
  Hat: "^",
  verbar: "|",
  lsqb: "[",
  rsqb: "]",
  lcub: "{",
  rcub: "}"
};

/**
 * One decoding pass over the HTML character references in `value`: decimal and hexadecimal
 * references with or without their semicolon (a browser accepts both), and the named ones in
 * {@link NAMED_REFERENCES}. Exactly one pass, as a browser does: `&amp;#58;` decodes to the
 * text `&#58;`, which is not a colon.
 */
function decodeCharacterReferences(value: string): string {
  return value.replace(/&(#x[0-9a-f]+|#[0-9]+|[a-z][a-z0-9]*);?/gi, (match: string, body: string) => {
    if (body.startsWith("#")) {
      const codePoint =
        body[1]?.toLowerCase() === "x" ? parseInt(body.slice(2), 16) : parseInt(body.slice(1), 10);
      return Number.isFinite(codePoint) && codePoint > 0 && codePoint <= 0x10ffff
        ? String.fromCodePoint(codePoint)
        : "";
    }
    // A named reference is only a reference with its semicolon (`&colon;`), unlike a numeric one.
    if (!match.endsWith(";")) {
      return match;
    }
    const named = NAMED_REFERENCES[body];
    return named !== undefined ? named : match;
  });
}

interface ParsedAttribute {
  name: string;
  value: string | undefined;
}

interface ParsedTag {
  name: string;
  closing: boolean;
  selfClosing: boolean;
  attributes: ParsedAttribute[];
  /** Index just past the tag's `>`. */
  end: number;
}

const WHITESPACE = /\s/;

/**
 * What the parser remembers across the tags of one document, so that hostile input costs a
 * bounded amount however many tags it holds. Tokens are read by lookup rather than by scanning,
 * and a place a tag was already seen to fail from is not walked again.
 */
interface TagScan {
  html: string;
  /** For each index, the end of the run of attribute-name characters starting there. */
  nameEnds: Int32Array | undefined;
  /** For each index, the end of the run of unquoted-value characters starting there. */
  valueEnds: Int32Array | undefined;
  /**
   * Places a tag is known never to close from: twice a position for "between two attributes
   * there", twice it plus one for "just past an attribute's name there".
   */
  doomed: Set<number>;
  /** Where the next quote of each kind sits after a given quote, so a repeat costs nothing. */
  closes: Map<number, number>;
}

function createTagScan(html: string): TagScan {
  return { html, nameEnds: undefined, valueEnds: undefined, doomed: new Set(), closes: new Map() };
}

/**
 * The run table for a character class: entry `i` is the first index at or after `i` that is not
 * in the class. Built once, backwards, the first time a tag has attributes to read.
 */
function runEnds(html: string, inClass: (char: string) => boolean): Int32Array {
  const ends = new Int32Array(html.length + 1);
  ends[html.length] = html.length;
  for (let index = html.length - 1; index >= 0; index -= 1) {
    ends[index] = inClass(html[index] as string) ? (ends[index + 1] as number) : index;
  }
  return ends;
}

function isSpace(char: string): boolean {
  const code = char.charCodeAt(0);
  return code === 32 || (code >= 9 && code <= 13) || (code > 127 && WHITESPACE.test(char));
}

const isNameChar = (char: string): boolean => char !== "=" && char !== "/" && char !== ">" && !isSpace(char);
const isValueChar = (char: string): boolean => char !== ">" && !isSpace(char);

function closeOfQuote(scan: TagScan, quote: string, open: number): number {
  const known = scan.closes.get(open);
  if (known !== undefined) {
    return known;
  }
  const close = scan.html.indexOf(quote, open + 1);
  scan.closes.set(open, close);
  return close;
}

/**
 * Parses one `<...>` starting at `start`, or `undefined` when the text there is not a tag (a
 * bare `<` in prose, or an unterminated one at the end of the input).
 *
 * Hand-written rather than a regex because an attribute value may contain `>`
 * (`<a title="a > b">`), and a `[^>]*` pattern would truncate the tag there and leave the rest
 * of the attribute as text — which is exactly the seam an injection uses.
 *
 * The cost across a whole document stays linear. The caller resumes one character after a tag
 * that did not parse, so a document of many unterminated tags would otherwise be read to its end
 * once per tag. A tag that fails is read to the end only once: every place it passed between two
 * attributes, or just past a name, is remembered as one a tag cannot close from, and the next
 * tag stops on reaching it.
 */
function parseTag(scan: TagScan, start: number): ParsedTag | undefined {
  const html = scan.html;
  let i = start + 1;
  const closing = html[i] === "/";
  if (closing) {
    i += 1;
  }
  let nameEnd = i;
  while (nameEnd < html.length && /[a-zA-Z0-9-]/.test(html[nameEnd] as string)) {
    nameEnd += 1;
  }
  if (nameEnd === i || !/[a-zA-Z]/.test(html[i] as string)) {
    return undefined;
  }
  const name = html.slice(i, nameEnd).toLowerCase();
  i = nameEnd;

  const attributes: ParsedAttribute[] = [];
  const passed: number[] = [];
  let selfClosing = false;
  const fail = (): undefined => {
    for (const position of passed) {
      scan.doomed.add(position);
    }
    return undefined;
  };
  while (i < html.length) {
    if (scan.doomed.has(i * 2)) {
      return fail();
    }
    passed.push(i * 2);
    while (i < html.length && isSpace(html[i] as string)) {
      i += 1;
    }
    if (html[i] === ">") {
      return { name, closing, selfClosing, attributes, end: i + 1 };
    }
    if (html[i] === "/" && html[i + 1] === ">") {
      return { name, closing, selfClosing: true, attributes, end: i + 2 };
    }
    if (html[i] === "/") {
      selfClosing = true;
      i += 1;
      continue;
    }
    scan.nameEnds ??= runEnds(html, isNameChar);
    const attrEnd = scan.nameEnds[i] as number;
    if (attrEnd === i) {
      // Nothing recognizable left in this tag; treat the whole thing as unparseable.
      return fail();
    }
    if (scan.doomed.has(attrEnd * 2 + 1)) {
      return fail();
    }
    passed.push(attrEnd * 2 + 1);
    const attrName = html.slice(i, attrEnd).toLowerCase();
    i = attrEnd;
    while (i < html.length && isSpace(html[i] as string)) {
      i += 1;
    }
    if (html[i] !== "=") {
      attributes.push({ name: attrName, value: undefined });
      continue;
    }
    i += 1;
    while (i < html.length && isSpace(html[i] as string)) {
      i += 1;
    }
    const quote = html[i];
    if (quote === '"' || quote === "'") {
      const close = closeOfQuote(scan, quote, i);
      if (close === -1) {
        return fail();
      }
      attributes.push({ name: attrName, value: html.slice(i + 1, close) });
      i = close + 1;
      continue;
    }
    scan.valueEnds ??= runEnds(html, isValueChar);
    const valueEnd = scan.valueEnds[i] as number;
    attributes.push({ name: attrName, value: html.slice(i, valueEnd) });
    i = valueEnd;
  }
  return fail();
}

function escapeAttributeValue(value: string): string {
  // A bare `&` is escaped; one that already opens an entity is left alone, so an author's
  // `?a=1&amp;b=2` stays a working link instead of becoming `&amp;amp;`.
  return value
    .replace(/&(?!#?[a-zA-Z0-9]+;)/g, "&amp;")
    .replace(/"/g, "&quot;")
    .replace(/</g, "&lt;");
}

function keepAttribute(tag: string, attribute: ParsedAttribute): boolean {
  const name = attribute.name;
  // `on*` never survives, whatever else an allowlist might say about it.
  if (name.startsWith("on")) {
    return false;
  }
  const allowed =
    GLOBAL_ATTRIBUTES.has(name) ||
    ELEMENT_ATTRIBUTES[tag]?.has(name) === true ||
    name.startsWith("aria-");
  if (!allowed) {
    return false;
  }
  if (URL_ATTRIBUTES.has(name)) {
    return (
      attribute.value !== undefined &&
      isSafeUrl(attribute.value, tag === "img" && name === "src" ? "image" : "link")
    );
  }
  return true;
}

function serializeTag(tag: ParsedTag): string {
  // A link that opens a new tab never hands the page it came from to the tab it opens: the
  // author's own `rel` is rewritten to carry `noopener` and `noreferrer` whatever else it says,
  // and loses `opener`, which would give the new tab `window.opener` again.
  const guardsLink =
    tag.name === "a" && tag.attributes.some((attribute) => attribute.name === "target");
  const attributes = tag.attributes
    .filter((attribute) => !(guardsLink && attribute.name === "rel"))
    .filter((attribute) => keepAttribute(tag.name, attribute))
    .map((attribute) =>
      attribute.value === undefined
        ? ` ${attribute.name}`
        : ` ${attribute.name}="${escapeAttributeValue(attribute.value)}"`
    )
    .join("");
  const rel = guardsLink ? ` rel="${escapeAttributeValue(guardedRel(tag.attributes))}"` : "";
  // A picture never tells the server it is named by: the allowlist
  // keeps no `referrerpolicy` of its own, so this is the only one.
  const referrer = tag.name === "img" ? ' referrerpolicy="no-referrer"' : "";
  const close = SELF_CLOSING_TAGS.has(tag.name) ? " /" : "";
  return `<${tag.name}${attributes}${rel}${referrer}${close}>`;
}

/** The `rel` tokens of a new-tab link: the author's, without `opener`, plus `noopener noreferrer`. */
function guardedRel(attributes: readonly ParsedAttribute[]): string {
  const tokens: string[] = [];
  for (const attribute of attributes) {
    if (attribute.name !== "rel" || attribute.value === undefined) {
      continue;
    }
    // Character references are decoded first: `&#111;pener` is `opener` to a browser.
    for (const token of decodeCharacterReferences(attribute.value).split(/[\t\n\f\r ]+/)) {
      const lower = token.toLowerCase();
      if (lower.length > 0 && lower !== "opener" && !tokens.includes(lower)) {
        tokens.push(lower);
      }
    }
  }
  for (const required of ["noopener", "noreferrer"]) {
    if (!tokens.includes(required)) {
      tokens.push(required);
    }
  }
  return tokens.join(" ");
}

const CLOSE_SEARCHES = new Map<string, RegExp>();

/** Where `</name` next appears at or after `from`, matching the name's ASCII letters in either case; -1 for none. */
function indexOfClose(html: string, name: string, from: number): number {
  let search = CLOSE_SEARCHES.get(name);
  if (!search) {
    // No `u` flag: without it the case-insensitive match folds ASCII letters only, which is how
    // a browser reads the end of a script or style element.
    search = new RegExp(`</${name}`, "gi");
    CLOSE_SEARCHES.set(name, search);
  }
  search.lastIndex = from;
  return search.exec(html)?.index ?? -1;
}

/**
 * Author-written markup reduced to the allowlist above: unknown elements lose their tags but
 * keep their text, `script`-like elements lose their contents too, and every attribute that
 * could execute or navigate is dropped.
 *
 * Unbalanced input is normalized rather than trusted — an unclosed element is closed at the
 * end, and a stray closing tag is dropped — so the block cannot break out of its wrapper and
 * take the rest of the form's markup with it.
 */
export function sanitizeStaticHtml(html: string): string {
  if (typeof html !== "string" || html.length === 0) {
    return "";
  }

  let out = "";
  let i = 0;
  const open: string[] = [];
  // How many of each element are open, so a close tag with nothing to close is known at once
  // rather than found by searching the whole stack for it.
  const openCount = new Map<string, number>();
  const scan = createTagScan(html);

  while (i < html.length) {
    const lt = html.indexOf("<", i);
    if (lt === -1) {
      out += html.slice(i);
      break;
    }
    out += html.slice(i, lt);

    if (html.startsWith("<!--", lt)) {
      const end = html.indexOf("-->", lt);
      i = end === -1 ? html.length : end + 3;
      continue;
    }
    if (html.startsWith("<!", lt) || html.startsWith("<?", lt)) {
      const end = html.indexOf(">", lt);
      i = end === -1 ? html.length : end + 1;
      continue;
    }

    const tag = parseTag(scan, lt);
    if (!tag) {
      // Not a tag at all — a comparison in prose. Escape it so it stays prose.
      out += "&lt;";
      i = lt + 1;
      continue;
    }

    if (VOID_OF_CONTENT_TAGS.has(tag.name)) {
      // Skip to the matching close, dropping everything between. The search is case-folded in
      // place: lower-casing the document would change its length for some letters (a dotted
      // capital I), and the index found would no longer be an index into it.
      const closeIndex = indexOfClose(html, tag.name, tag.end);
      if (closeIndex === -1) {
        i = html.length;
        break;
      }
      const closeEnd = html.indexOf(">", closeIndex);
      i = closeEnd === -1 ? html.length : closeEnd + 1;
      continue;
    }

    i = tag.end;

    if (!ALLOWED_TAGS.has(tag.name)) {
      // Unknown element: drop the tag, keep whatever it wrapped.
      continue;
    }

    if (tag.closing) {
      const depth = openCount.get(tag.name) ? open.lastIndexOf(tag.name) : -1;
      if (depth === -1) {
        // A close with no open — dropping it is what keeps the block balanced.
        continue;
      }
      // Close anything left open inside it, innermost first.
      for (let index = open.length - 1; index >= depth; index -= 1) {
        const closed = open[index] as string;
        out += `</${closed}>`;
        openCount.set(closed, (openCount.get(closed) ?? 1) - 1);
      }
      open.length = depth;
      continue;
    }

    out += serializeTag(tag);
    if (!tag.selfClosing && !SELF_CLOSING_TAGS.has(tag.name)) {
      open.push(tag.name);
      openCount.set(tag.name, (openCount.get(tag.name) ?? 0) + 1);
    }
  }

  for (let index = open.length - 1; index >= 0; index -= 1) {
    out += `</${open[index] as string}>`;
  }
  return out;
}
